import java.util.*;import com.koios.game.arpg.*;import com.koios.game.model.item.*;import com.koios.game.model.player.*;import com.koios.network.*;import com.koios.client.arpg.ItemTooltipCache;
public final class CraftingAuditCheck {
 static int checks;static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
 static void refresh(Player p,ItemTooltipCache cache){for(GamePacket packet:((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets)if(packet.getOpcode()==126){String text=packet.readString();int widget=packet.readShortA()&65535;if(widget==ItemTooltip.CHANNEL)cache.accept(text);}((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.clear();}
 static Item fresh(ItemRoll.Rarity rarity,boolean identified,int corruption){Item i=AffixCatalog.starter(true);i.setRoll(i.getRoll().changed(rarity,identified,corruption,AffixCatalog.roll(i,rarity,new Random(11)),null));return i;}
 static void attempt(Player p,int currency,Item target,boolean success){p.getInventory().set(0,target);p.getInventory().set(1,new Item(currency,3));Item before=target.copy();CraftingCurrency.use(p,1,0);check(p.getInventory().getCount(currency)==(success?2:3),"Consumption follows success for currency "+currency);check(target.getRoll().getInstanceId().equals(before.getRoll().getInstanceId()),"Craft preserves unique item identity");if(!success)check(ItemTooltip.lines(target,true).equals(ItemTooltip.lines(before,true)),"Rejected craft does not alter target");}
 public static void main(String[] args)throws Exception{
  PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("craftaudit",48);p.allowSaveRequests=false;p.setAttribute("tutorial-stage",11);PrototypeIntegrationCheck.idle(p);ItemTooltipCache cache=new ItemTooltipCache();
  for(int id=22400;id<=22406;id++){Item i=new Item(id,5);check(!i.hasRoll()&&ItemTooltip.supports(i),"Nonrolled material/scroll supported "+id);String text=String.join(" ",ItemTooltip.lines(i,false));check(text.contains(id==22406?"Read inside a map":"Right-click Use"),"Player-facing use instructions "+id);cache.accept(ItemTooltip.payload(3214,0,i));check(cache.get(3214,0,id)!=null,"Payload decodes normal item "+id);}
  ((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.clear();ActionSender.sendInterfaceItems(p,3214,new Item[]{new Item(22400,5),new Item(22406,2)});refresh(p,cache);check(cache.get(3214,0,22400)!=null&&cache.get(3214,1,22406)!=null,"Real bulk inventory update sends nonrolled metadata");ActionSender.sendInterfaceItems(p,3214,new Item[]{null,new Item(995,1)});refresh(p,cache);check(cache.get(3214,0,22400)==null&&cache.get(3214,1,22406)==null,"Bulk refresh clears stale metadata for removed/replaced slots");ItemTooltip.send(p,3214,0,new Item(22405,1));refresh(p,cache);check(cache.get(3214,0,22405)!=null,"Single-slot metadata updates");ItemTooltip.send(p,3214,0,null);refresh(p,cache);check(cache.get(3214,0,22405)==null,"Single-slot removal clears tooltip");
  attempt(p,22400,fresh(ItemRoll.Rarity.NORMAL,true,0),true);attempt(p,22400,fresh(ItemRoll.Rarity.MAGIC,true,0),false);attempt(p,22400,fresh(ItemRoll.Rarity.RARE,true,0),false);attempt(p,22403,fresh(ItemRoll.Rarity.NORMAL,true,0),true);attempt(p,22403,fresh(ItemRoll.Rarity.MAGIC,true,0),false);attempt(p,22401,fresh(ItemRoll.Rarity.NORMAL,true,0),false);attempt(p,22401,fresh(ItemRoll.Rarity.RARE,true,0),true);attempt(p,22405,fresh(ItemRoll.Rarity.RARE,false,0),true);attempt(p,22405,fresh(ItemRoll.Rarity.RARE,true,0),false);attempt(p,22404,fresh(ItemRoll.Rarity.RARE,true,0),true);attempt(p,22404,fresh(ItemRoll.Rarity.RARE,true,1),true);attempt(p,22404,fresh(ItemRoll.Rarity.RARE,true,2),false);
  for(int id:new int[]{22400,22401,22402,22403,22404})attempt(p,id,fresh(ItemRoll.Rarity.NORMAL,false,0),false);for(int id:new int[]{22400,22401,22402,22403})attempt(p,id,fresh(ItemRoll.Rarity.RARE,true,1),false);
  System.out.println("Passed "+checks+" crafting consumption, constraints and real tooltip-cache refresh checks.");
 }
}
